import { spawnSync } from 'node:child_process';
import { writeFileSync, readFileSync } from 'node:fs';
const work = '/workspace/vibe-check/tmp/optimization-20261012/tokenizer';
const runtime = process.argv[2] ?? 'node';
const phase = process.argv[3] ?? 'pathological';
const rows = [];
function child(args, timeout = 5000) {
  const started = performance.now();
  const result = spawnSync('mise', ['exec','--',runtime,`${work}/measure.ts`, ...args], {
    timeout, killSignal: 'SIGKILL', encoding:'utf8', maxBuffer: 2 * 1024 * 1024
  });
  const lines = result.stdout.trim().split('\n').filter(Boolean);
  const row = { args, externalDeadlineMs: timeout, outerMs: performance.now() - started,
    status: result.status, signal: result.signal, error: result.error?.code,
    observation: result.status === 0 ? JSON.parse(lines.at(-1)) : undefined,
    stderrExcerpt: result.status === 0 ? undefined : result.stderr.slice(-1000) };
  rows.push(row); console.log(JSON.stringify(row));
}
if (phase === 'pathological') {
  for (const mode of ['raw','run','port']) for (const kind of ['template','comment']) {
    const sizes = kind === 'template' ? [16,20,24] : [2000,8000,16000];
    for (const prefix of ['0','1']) for (const n of sizes) for (let block=0;block<2;block++)
      for (const variant of block % 2 ? ['candidate','baseline'] : ['baseline','candidate']) child([variant,mode,kind,String(n),prefix]);
  }
} else if (phase === 'corpus') {
  for (let block=0;block<(runtime==='bun'?4:8);block++) for (const variant of block%2 ? ['candidate','baseline'] : ['baseline','candidate'])
    child([variant,'corpus','real'],15000);
} else throw new Error('bad phase');
writeFileSync(`${work}/${phase}-${runtime}.json`,JSON.stringify({ runtime, phase, rows,
  protocol: 'fresh child per operation; alternating AB/BA; external hard timeout via spawnSync killSignal SIGKILL; cancelled/timeout samples not normal completion; raw/run/port separate overlapping layers' },null,2)+'\n');

import { strict as assert } from 'node:assert';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = '/workspace/vibe-check';
const work = `${root}/tmp/optimization-20261012/tokenizer`;
const owner = 'src/package-checks/function-metrics/analyzer';
const digest = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
async function modules(base: string) {
  const load = (file: string) => import(pathToFileURL(`${base}/${file}`).href);
  const shared = await load(`${owner}/shared/code-reader.ts`);
  const registry = await load(`${owner}/reader-registry.ts`);
  const adapter = await load('src/package-checks/function-metrics/analyzer-adapter.ts');
  let raw: unknown[] = [];
  const original = shared.CodeReader.generateTokens;
  shared.CodeReader.generateTokens = function (source: string, addition: string, factory?: Function, template?: string) {
    const lineStarts = [0];
    for (const match of source.matchAll(/\n/g)) lineStarts.push(match.index + 1);
    const lineAt = (offset: number) => {
      let lo = 0, hi = lineStarts.length;
      while (lo < hi) { const mid = (lo + hi) >>> 1; if (lineStarts[mid] <= offset) lo = mid + 1; else hi = mid; }
      return lo;
    };
    return original.call(this, source, addition, (match: any) => {
      raw.push({ text: match.text, startOffset: match.startOffset,
        line: lineAt(match.startOffset) });
      return factory ? factory(match) : match.text;
    }, template);
  };
  return { shared, registry, adapter, stream(reader: any, source: string) {
    raw = [];
    const tokens = [...reader.generateTokens(source)];
    return { raw, tokens };
  } };
}
const before = await modules(`${work}/baseline`);
const after = await modules(`${work}/candidate-v3.1`);
const rows: unknown[] = [];
function check(label: string, readerName: string, source: string, filename?: string) {
  const a = before.registry.languages().find((reader: any) => reader.name === readerName);
  const b = after.registry.languages().find((reader: any) => reader.name === readerName);
  assert.ok(a && b, readerName);
  const baseline = before.stream(a, source);
  const candidate = after.stream(b, source);
  assert.deepEqual(candidate, baseline, label);
  if (filename) {
    assert.deepEqual(after.adapter.analyzeFunctionMetricsSources({ files: [{ path: filename, source }] }),
      before.adapter.analyzeFunctionMetricsSources({ files: [{ path: filename, source }] }), `${label}: complete adapter`);
  }
  rows.push({ label, readerName, bytes: Buffer.byteLength(source), rawMatches: baseline.raw.length,
    tokens: baseline.tokens.length, rawDigest: digest(baseline.raw), tokenDigest: digest(baseline.tokens) });
}
const smoke = process.argv.includes('--smoke');
const prefixes = ['','/* ordinary */\nconst x = `closed ${value}`;\nfunction f(){ return 1; }\n'];
for (const [prefixIndex, prefix] of prefixes.entries()) {
  for (const n of smoke ? [2] : [0,1,2,4,8,12,16]) {
    for (const [reader, file] of [['TypeScriptReader','input.ts'],['TSXReader','input.tsx']])
      check(`template-${prefixIndex}-${n}`, reader, prefix + '`' + '${x}'.repeat(n), file);
  }
  for (const n of smoke ? [2] : [0,1,2,8,64,256])
    check(`comment-${prefixIndex}-${n}`, 'CLikeReader', prefix + '/* '.repeat(n), 'input.c');
}
const edges = [
  '`ok`', '`a ${x} b`', '`a ${"tick`here"} b`', '`a ${\'tick`here\'} b`', '`a \\` b`',
  '`a ${x}', '`a ${"unterminated}', '`\\\n${x}', '\u{1f600}`${x}',
  '/*/', '/**/', '/* a /* b */ tail /*', '/* a\n*/ /* /*',
  '#define X \\\n/* ordinary */\n/* /*', '\u001c \r\n/* /*',
  'const a = `x`;\nconst b = `${x}', 'const a = `x`;\nconst b = `\\`',
  '/* closed */ \t \r\n/* /* /* ', '`closed` \t \r\n`${x}${x}${x}',
  '/* closed */ \t\u001c /* /* ', '`closed` \t\u001c `${x}${x}',
  '"/*" \'*/\' /* tail', '\ud800/* /*', '\udc00`a', '`a`/* tail',
];
for (const [i, source] of edges.entries()) for (const reader of ['CLikeReader','TypeScriptReader','TSXReader'])
  check(`edge-${reader}-${i}`, reader, source);
// Raw zero-width and custom-factory semantics are checked directly, not inferred from metrics.
for (const source of ['\u{1f600}/* ', '\ud800x', '\r\n#x\n', '']) {
  for (const addition of ['|(?=.)','|(?=\u{1f600})','|(?=$)','|(?i)(?=x)']) {
    const capture = (shared: any) => {
      const matches: unknown[] = [];
      const iterator = shared.CodeReader.generateTokens(source, addition, (match: any) => {
        matches.push({ text: match.group(0), offset: match.start() }); return match.text;
      });
      return { matches, tokens: [...iterator] };
    };
    assert.deepEqual(capture(after.shared), capture(before.shared), 'zero-width/UTF16/factory');
  }
}
if (!smoke) {
  const evidence = `${root}/${owner}/fixtures/lizard-1.24.1/evidence`;
  const oracle = JSON.parse(readFileSync(`${evidence}/lizard-1.24-selected-extension-observations.json`, 'utf8'));
  for (const fixture of oracle.fixtures) {
    const source = readFileSync(resolve(root, fixture.fixture), 'utf8');
    assert.equal(createHash('sha256').update(source).digest('hex'), fixture.sourceSha256);
    check(fixture.fixture, fixture.readerClass, source, fixture.fixture);
  }
  if (process.argv.includes('--corpus')) {
    const manifest = JSON.parse(readFileSync(`${work}/corpus-manifest.json`,'utf8'));
    for (const file of manifest) {
      const source = readFileSync(`${work}/frozen-input/${file.path}`,'utf8');
      assert.equal(createHash('sha256').update(source).digest('hex'),file.sha256);
      const reader = before.registry.get_reader_for(file.path);
      check(file.path, reader.name, source, file.path);
    }
  }
}
const output = { runtime: process.versions, mode: smoke ? 'smoke' : 'synthetic+110-current-oracle-fixtures',
  limits: { syntheticTemplateN: smoke ? 2 : 16, syntheticCommentN: smoke ? 2 : 256 },
  sourceRoot: root, candidateRoot: `${work}/candidate-v3.1`, rows, zeroWidthMatrices: 16,
  note: 'raw factory events include source-relative UTF16 offset and LF source line; final transformed token stream separately compared; upstream oracle JSON unchanged' };
const target = `${work}/differential-v3.1-${process.versions.bun ? 'bun' : 'node'}${smoke ? '-smoke' : ''}.json`;
writeFileSync(target, JSON.stringify(output, null, 2) + '\n');
console.log(JSON.stringify({ target, rows: rows.length, result: 'equal' }));

